mongodb:createCollection.mongodb:options:
{
  "validator": {
    "$jsonSchema": {
      "bsonType": "object",
      "required": [
        "order_id",
        "user_id",
        "status",
        "timestamp",
        "payment_amount"
      ],
      "properties": {
        "order_id": {
          "bsonType": "long",
          "description": "Order identifier is required"
        },
        "user_id": {
          "bsonType": "long",
          "description": "User identifier is required"
        },
        "status": {
          "bsonType": "string",
          "description": "Payment status is required"
        },
        "timestamp": {
          "bsonType": "date",
          "description": "Payment timestamp is required"
        },
        "payment_amount": {
          "bsonType": "decimal",
          "minimum": 0,
          "description": "Payment amount must be non-negative"
        }
      }
    }
  },
  "validationLevel": "strict",
  "validationAction": "error"
}
